root.command:
IF OBJECT_ID(N'dbo.ContactTypesTbl', N'U') IS NOT NULL AND OBJECT_ID(N'dbo.ContactsTbl', N'U') IS NOT NULL BEGIN DECLARE @SupplierTypeId INT = ( SELECT TOP 1 ContactTypeID FROM dbo.ContactTypesTbl WHERE LTRIM(RTRIM(ContactTypeDesc)) = N'Supplier' ORDER BY ContactTypeID);
IF @SupplierTypeId IS NOT NULL BEGIN -- Cape Coffee Beans is a client; clear if it was tagged Supplier by an older broad match UPDATE dbo.ContactsTbl SET ContactTypeID = NULL WHERE ContactTypeID = @SupplierTypeId AND CompanyName LIKE N'%Cape Coffee Beans%';
UPDATE dbo.ContactsTbl SET ContactTypeID = @SupplierTypeId WHERE (ContactTypeID IS NULL OR ContactTypeID <> @SupplierTypeId) AND ( CompanyName LIKE N'%Zuka%' OR CompanyName LIKE N'%Marunic%' OR CompanyName LIKE N'%Float%' OR (CompanyName LIKE N'%Cape Coffee%' AND CompanyName NOT LIKE N'%Beans%') ); END END
